dtsPropsFor.Button:
/** Visual style. `primary` is the Sky Blue call to action; `danger`/`success` are status actions. */
variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'success';
size?: 'sm' | 'md' | 'lg';
/** Shows an inline spinner and blocks interaction. Implies disabled. */
loading?: boolean;
disabled?: boolean;
/** Stretches the button to the full width of its container. */
fullWidth?: boolean;
leftIcon?: React.ReactNode;
rightIcon?: React.ReactNode;
type?: 'button' | 'submit' | 'reset';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Card:
/** `glass` applies the frosted `.glass-card` treatment used over imagery. */
variant?: 'default' | 'elevated' | 'outlined' | 'glass';
padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl';
/** Adds the lift-on-hover transition. */
hover?: boolean;
/** Adds cursor + press affordances for a clickable card. */
interactive?: boolean;
className?: string;
children?: React.ReactNode;

dtsPropsFor.Input:
label?: string;
/** Native input type, e.g. 'text' | 'email' | 'password' | 'number'. */
type?: string;
size?: 'sm' | 'md' | 'lg';
variant?: 'default' | 'filled' | 'outlined';
/** Applies the error border. Pair with errorMessage to show help text. */
error?: boolean;
errorMessage?: string;
placeholder?: string;
leftIcon?: React.ReactNode;
rightIcon?: React.ReactNode;
disabled?: boolean;
/** Renders a red asterisk beside the label. */
required?: boolean;
value?: string | number;
defaultValue?: string | number;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
className?: string;

dtsPropsFor.LoadingSpinner:
/** Status text shown under the spinner; also used as the aria-label. */
text?: string;
/** Renders as a fixed full-viewport overlay instead of an inline block. */
fullScreen?: boolean;
className?: string;

dtsPropsFor.ServiceTabs:
/** Which service tab reads as current. */
active?: 'cruise' | 'flight' | 'packages' | 'hotels';
className?: string;

dtsPropsFor.Price:
/**
 * Amount in USD, converted and formatted into the viewer's selected currency.
 * May also be an object carrying its own currency, which is converted from there.
 */
amount: number | string | { amount: number; currency: string };
/**
 * Appends the ISO currency code after the amount.
 * NOTE: the code is rendered with a hardcoded white text colour, so it is
 * only visible on a dark surface. On a light background it renders invisibly.
 */
showCode?: boolean;
className?: string;
